import{_ as p,a0 as r,w as l,s as d,ao as o,I as n,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何从 Debian 稳定版切换到测试版 | LCTT x X-CMD","titleTemplate":false,"description":"如何从 Debian 稳定版切换到测试版 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从 Debian 稳定版切换到测试版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从 Debian 稳定版切换到测试版 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing","title":"如何从 Debian 稳定版切换到测试版","tag":"202302","desc":""},"relativePath":"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing.md","filePath":"[post].md"}'),g={name:"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing.md"};function b(u,s,h,k,m,f){const e=r("Link");return l(),d("div",null,[s[28]||(s[28]=o('<h1 id="如何从-debian-稳定版切换到测试版" tabindex="-1">如何从 Debian 稳定版切换到测试版 <a class="header-anchor" href="#如何从-debian-稳定版切换到测试版" aria-label="Permalink to “如何从 Debian 稳定版切换到测试版”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/08/122659a4919hso9onkbmun.jpg" alt=""></p><p>如果你正在寻找最稳定的 Linux 发行版，当然，Debian 是正确的选择。</p><p>特别是如果你打算在服务器上使用它。</p><p>但是，在桌面方面，情况就有点不同了。我的意思是，你得到的软件包至少是一年前的，对新时代硬件的支持甚至更糟。</p><p>那么，在这种情况下，你会怎么做呢？好吧，你可以使用 Debian <ruby>测试版<rt>Testing</rt></ruby>。</p><p>但在跳到解释部分之前，让我们简单了解一下 Debian 测试版。</p><h3 id="什么是-debian-测试版" tabindex="-1">什么是 Debian 测试版？ <a class="header-anchor" href="#什么是-debian-测试版" aria-label="Permalink to “什么是 Debian 测试版？”">​</a></h3><p>Debian 社区为你提供 3 种不同的 Debian：</p><ul><li>Debian <ruby>稳定版<rt>Stable</rt></ruby>（你从他们的主页上默认得到的东西）。</li><li>Debian <ruby>测试版<rt>Testing</rt></ruby>（有<strong>新的软件包</strong>，比 Debian 不稳定版更少出现故障）。</li><li>Debian <ruby>不稳定版<rt>Unstable</rt></ruby>（拥有最新的软件包，是<strong>所有版本中最脆弱的</strong>）。</li></ul><p>因此，Debian 测试版可以被认为是稳定性和新软件包之间的一个折中点。</p><p>我已经玩了一段时间的 Debian 测试版，没有遇到任何问题。</p><p>事实上，许多 Debian 用户喜欢测试版而不是稳定版。尽管名字叫“测试”，但它是相当可用的。</p><p>但是，<strong>我还是建议你在虚拟机上进行实验</strong>，尝试用你的主要工具来使用它，如果事情进展顺利，你可以在主系统中应用这些变化。</p><h3 id="从-debian-稳定版切换到-debian-测试版" tabindex="-1">从 Debian 稳定版切换到 Debian 测试版 <a class="header-anchor" href="#从-debian-稳定版切换到-debian-测试版" aria-label="Permalink to “从 Debian 稳定版切换到 Debian 测试版”">​</a></h3><p><strong>警告：你不能从 Debian 测试版降级到 Debian 稳定版，因为安装脚本和安装工具只是为了用新版本替换旧版本而设计的。</strong></p>',16)),n("p",null,[s[1]||(s[1]=t("另外，我建议在你的主机上应用上述步骤之前，",-1)),i(e,{href:"https://itsfoss.com/backup-restore-linux-timeshift/"},{default:a(()=>[...s[0]||(s[0]=[t("使用 timeshift 创建一个备份",-1)])]),_:1}),s[2]||(s[2]=t(" 。",-1))]),s[29]||(s[29]=o('<p>首先，使用给定的命令更新现有的软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>接下来，复制原始的 <code>sources.list</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/apt/sources.list sources.list.backup</span></span></code></pre></div><p>现在，让我们开始第一步的工作。</p><h4 id="步骤-1-编辑-sources-list-文件" tabindex="-1">步骤 1：编辑 sources.list 文件 <a class="header-anchor" href="#步骤-1-编辑-sources-list-文件" aria-label="Permalink to “步骤 1：编辑 sources.list 文件”">​</a></h4>',6)),n("p",null,[s[4]||(s[4]=t("有两种方法可以编辑 ",-1)),s[5]||(s[5]=n("code",null,"sources.list",-1)),s[6]||(s[6]=t(" 文件。要么你可以用 ",-1)),s[7]||(s[7]=n("code",null,"testing",-1)),s[8]||(s[8]=t(" 手动改变当前版本的名称，要么你可以 ",-1)),i(e,{href:"https://linuxhandbook.com/sed-command-basics/"},{default:a(()=>[...s[3]||(s[3]=[t("使用 sed 命令",-1)])]),_:1}),s[9]||(s[9]=t(" 来完成。",-1))]),s[30]||(s[30]=o('<p>而我要用第二种方法来使整个过程更简单。你只需要使用给定的命令，它就会为你把 <code>bullseye</code> 替换成 <code>testing</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo sed -i &#39;s/bullseye/testing/g&#39; /etc/apt/sources.list</span></span></code></pre></div><p>现在，打开你的终端，使用给定的命令来打开 <code>sources.list</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/apt/sources.list</span></span></code></pre></div><p>并注释掉有 <code>security.debian.org</code> 和任何以 <code>updates</code> 结尾的行，如下所示：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/comment-out-security-sources.gif" alt="comment out security sources"></p><p>如果你像我一样使用 <code>nano</code>，你可以按 <code>Alt + /</code> 跳到该行的最后。然后你要添加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://security.debian.org testing-security main</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/2.-add-line-to-keep-track-of-testing-in-debian.png" alt="add line to keep track of testing in debian"></p>',9)),n("p",null,[s[11]||(s[11]=t("然后 ",-1)),i(e,{href:"https://linuxhandbook.com/nano-save-exit/"},{default:a(()=>[...s[10]||(s[10]=[t("保存修改并退出 nano",-1)])]),_:1}),s[12]||(s[12]=t(" 文本编辑器。",-1))]),s[31]||(s[31]=o('<h4 id="步骤-2-更新仓库并安装新的软件包" tabindex="-1">步骤 2：更新仓库并安装新的软件包 <a class="header-anchor" href="#步骤-2-更新仓库并安装新的软件包" aria-label="Permalink to “步骤 2：更新仓库并安装新的软件包”">​</a></h4><p>现在，更新仓库索引，它会显示大量的更新等待：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/update-repository-in-linux.png" alt="update repository in linux"></p><p>现在，你可以使用给定的命令，它将为你提供最新的软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>坐下来，放松一下，因为这将需要一些时间。</p><p>完成后，它将向你展示从 Debian 稳定版切换到测试版时的变化列表：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/packages-that-are-updated-when-switched-to-debian-testing.png" alt="packages that are updated when switched to debian testing"></p><p>如果你愿意，你可以阅读，或者你可以<strong>直接按</strong> <code>q</code> 继续。</p><p>现在，它会告诉你，你系统上安装的一些库需要重新启动。按 <code>TAB</code> 键，它将选择 “OK”，然后按<strong>回车</strong>：。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/libraries-needs-to-be-restarted-after-update.png" alt="libraries needs to be restarted after update"></p><p>接下来，它会问你是否要在软件包升级期间重启服务。这里你有一个选择。由于我只做桌面使用，我将选择 “YES”。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/restart-services-during-package-upgrades-without-asking.png" alt="restart services during package upgrades without asking?"></p><p>完成后，你可以重启你的系统，然后使用下面的命令，让你刚才的改变完全生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>现在，重启你的系统，你就会拥有最新的软件包。比如<strong>我进入系统时我在运行 GNOME 43</strong>：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/running-gnome-43-in-debian.png" alt="running gnome 43 in debian"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本教程中，我解释了如何从 Debian 稳定版切换到 Debian 测试版。我希望这对你会有帮助。</p><p>如果你遇到任何问题或有任何疑问，请在评论中告诉我。</p><hr>',22)),n("p",null,[s[14]||(s[14]=t("via: ",-1)),i(e,{href:"https://itsfoss.com/switch-debian-stable-testing/"},{default:a(()=>[...s[13]||(s[13]=[t("https://itsfoss.com/switch-debian-stable-testing/",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=t("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...s[15]||(s[15]=[t("Sagar Sharma",-1)])]),_:1}),s[20]||(s[20]=t(" 选题：",-1)),i(e,{href:"https://github.com/lkxed"},{default:a(()=>[...s[16]||(s[16]=[t("lkxed",-1)])]),_:1}),s[21]||(s[21]=t(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[17]||(s[17]=[t("geekpi",-1)])]),_:1}),s[22]||(s[22]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[18]||(s[18]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[23]||(s[23]=[t("LCTT",-1)])]),_:1}),s[26]||(s[26]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[24]||(s[24]=[t("Linux中国",-1)])]),_:1}),s[27]||(s[27]=t(" 荣誉推出",-1))])])}const D=p(g,[["render",b]]);export{y as __pageData,D as default};
